/bin/bash -lc "python3 - <<'PY'
from zipfile import ZipFile
from xml.etree import ElementTree as ET
p='/home/user/Desktop/30_1.pptx'
ns={'p':'http://schemas.openxmlformats.org/presentationml/2006/main','a':'http://schemas.openxmlformats.org/drawingml/2006/main'}
targets={3:'Google Shape;446;p18',4:'Google Shape;466;p19',6:'Google Shape;684;p22'}
with ZipFile(p) as z:
 for slide,name in targets.items():
  root=ET.fromstring(z.read(f'ppt/slides/slide{slide}.xml'))
  for el in root.iter():
   c=el.find('.//p:cNvPr',ns)
   if c is not None and c.get('name')==name:
    ext=el.find('.//a:xfrm/a:ext',ns)
    print(f'slide {slide}: xml height {int(ext.get(\"cy\"))/360000:.2f} cm')
    break
PY"

